 DROP FUNCTION cjams.getadoptionchecklist(v_adoptionplanningid uuid);
 CREATE OR REPLACE FUNCTION cjams.getadoptionchecklist(v_adoptionplanningid uuid)                                                                                                                                                                                                                                                                            
  RETURNS TABLE(adoptionchecklistid uuid, adoptionplanningid uuid, disclosuredate timestamp without time zone, personinfomation character varying, worker character varying, localdepartment character varying, nonstaffmember character varying, siblingage integer, siblinginformation character varying, remarks text, status text, approvedby character varying, approvedon timestamp without time zone, submitby character varying, tosecurityusersid character varying, submiton timestamp without time zone, adoptionchecklist json)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                            
 AS $function$                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                              
 BEGIN                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                              
 RETURN  query                                                                                                                                                                                                                                                                                                                                                
 select adcl.adoptionchecklistid,adcl.adoptionplanningid,adcl.disclosuredate,adcl.personinfomation,                                                                                                                                                                                                                                                           
        adcl.worker,adcl.localdepartment,adcl.nonstaffmember,adcl.siblingage,adcl.siblinginformation,adcl.remarks ,                                                                                                                                                                                                                                           
 (select rs.typedescription AS status from routing r                                                                                                                                                                                                                                                                                                          
 INNER    JOIN    routingstatustype    rs    ON    r.routingstatustypeid    =    rs.sequencenumber    AND    rs.activeflag    =1                                                                                                                                                                                                                              
 where  r.objectid  =  adcl.adoptionplanningid::character  varying  and  r.eventcode  =  'ADPR'  and  r.activeflag    =1 order by r.insertedon desc limit 1                                                                                                                                                                                                                             
 )                                                                                                                                                                                                                                                                                                                                                            
 ,(select up.fullname approvedby from routing r                                                                                                                                                                                                                                                                                                          
 INNER    JOIN    routingstatustype    rs    ON    r.routingstatustypeid    =    rs.sequencenumber    AND    rs.activeflag    =1
 inner join userprofile up on up.securityusersid = r.fromsecurityusersid
 where  r.objectid  = adcl.adoptionplanningid::character  varying   and  r.eventcode  =  'ADPR'  and  r.routingstatustypeid = 16  order by r.insertedon desc limit 1                                                                                                                                                                                                                             
 ),
 (select r.insertedon approvedon from routing r                                                                                                                                                                                                                                                                                                          
 INNER    JOIN    routingstatustype    rs    ON    r.routingstatustypeid    =    rs.sequencenumber    AND    rs.activeflag    =1                                                                                                                                                                                                                              
 where  r.objectid  = adcl.adoptionplanningid::character  varying   and  r.eventcode  =  'ADPR'  and  r.routingstatustypeid = 16  order by r.insertedon desc limit 1                                                                                                                                                                                                                              
 ),
 (select up.fullname submitby from routing r
 inner join userprofile up on up.securityusersid = r.fromsecurityusersid
where  r.objectid  = adcl.adoptionplanningid::character  varying  and  r.eventcode  =  'ADPR'  and  r.routingstatustypeid = 15 order by r.insertedon desc limit 1 ),
 (select up.securityusersid tosecurityusersid from routing r
 inner join userprofile up on up.securityusersid = r.fromsecurityusersid
where  r.objectid  = adcl.adoptionplanningid::character  varying  and  r.eventcode  =  'ADPR'  and  r.routingstatustypeid = 15 order by r.insertedon desc limit 1 ),
(select r.insertedon submiton from routing r                                                                                                                                                                                                                              
where  r.objectid  = adcl.adoptionplanningid::character  varying   and  r.eventcode  =  'ADPR'  and  r.routingstatustypeid = 15 order by r.insertedon desc limit 1),
(SELECT json_agg(x) AS adoptionchecklist FROM(                                                                                                                                                                                                                                                                                                              
                 SELECT                                                                                                                                                                                                                                                                                                                                       
                 cl.checklistid,cl.checklistname,cl.description  as  checklistdesc,adpd.isselected,adpd.remarks                                                                                                                                                                                                                                               
                 from adoptionchecklistdetails adpd                                                                                                                                                                                                                                                                                                           
                 LEFT JOIN checklist  cl on cl.checklistid = adpd.checklistid                                                                                                                                                                                                                                                                                 
                 INNER  JOIN  referencevalues  rvs  ON  rvs.ref_key= cl.checklisttypekey  AND  rvs.activeflag=1                                                                                                                                                                                                                                               
                 WHERE  adpd.adoptionchecklistid= adcl.adoptionchecklistid   AND  adpd.activeflag=1                                                                                                                                                                                                                                                           
         )  x)                                                                                                                                                                                                                                                                                                                                                
 from adoptionchecklist adcl                                                                                                                                                                                                                                                                                                                                  
 where adcl.adoptionplanningid = v_adoptionplanningid;                                                                                                                                                                                                                                                                                                        
 END;                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                              
 $function$                                                                                                                                                                                                                                                                                                                                                   

